43	  metrics.forEach(metric => {
44	    const metricLabel = getMetricLabel(metric);
45	    aggregates[metricLabel] = {
46	      operator: aggregation,
47	      column: metricLabel,
48	    };
49	  });
50	
51	  return {
52	    operation: 'aggregate',
53	    options: {
54	      groupby: [],
55	      aggregates,
56	    },
57	  };
