  [QueryMode.Aggregate]: t('Aggregate'),
  [QueryMode.Raw]: t('Raw records'),
};

export const DEFAULT_SORT_SERIES_DATA: SortSeriesData = {
  sort_series_type: SortSeriesType.Sum,
  sort_series_ascending: false,
};

/**
 * Centralized aggregation methods for computing a headline number from a
 * series of values on the client side. Keys are lowercase so callers can look
 * them up with `String(aggregation).toLowerCase()`. Each entry exposes a human
 * readable `label` and a `compute` function returning the aggregated value (or
 * `null` when there is nothing to aggregate).
 */
export const aggregationChoices: Record<
  string,
  { label: string; compute: (data: number[]) => number | null }
> = {
  raw: {
    label: t('None'),
    compute: (data: number[]) =>
      data.length ? data[data.length - 1] : null,
  },
  last_value: {
    label: t('Last Value'),
    compute: (data: number[]) =>
      data.length ? data[data.length - 1] : null,
  },
  sum: {
    label: t('Total (Sum)'),
    compute: (data: number[]) =>
      data.length ? data.reduce((acc, val) => acc + val, 0) : null,
  },
  mean: {
    label: t('Average (Mean)'),
    compute: (data: number[]) =>
      data.length
        ? data.reduce((acc, val) => acc + val, 0) / data.length
        : null,
  },
  min: {
    label: t('Minimum'),
    compute: (data: number[]) => (data.length ? Math.min(...data) : null),
  },
  max: {
    label: t('Maximum'),
    compute: (data: number[]) => (data.length ? Math.max(...data) : null),
  },
  median: {
    label: t('Median'),
    compute: (data: number[]) => {
      if (!data.length) {
        return null;
      }
      const sorted = [...data].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      return sorted.length % 2 !== 0
        ? sorted[mid]
        : (sorted[mid - 1] + sorted[mid]) / 2;
    },
  },
} as const;

export const SORT_SERIES_CHOICES = [
